"""Experiment tracking & results infrastructure.

Every training run writes a fully reproducible record here. The guiding principle:
*no number in the paper is ever hand-typed* — figures and tables are generated by
scripts that read the master results table this module maintains.

A :class:`Run` creates a unique timestamped directory under ``outputs/runs/``,
captures config + git + environment metadata, lets you log metrics / curves /
artifacts / figures during training, and on :meth:`Run.finish` appends exactly one
flattened row to the project-wide master tables ``outputs/results.csv`` and
``outputs/results.jsonl``.

This stage is pure engineering: no math, no geometry, no training logic.
"""

from __future__ import annotations

import hashlib
import json
import os
import platform as _platform
import re
import shutil
import subprocess
from datetime import datetime, timezone
from pathlib import Path

import pandas as pd
import yaml

# ---------------------------------------------------------------------------
# Task 5 — Atomic write helpers
# ---------------------------------------------------------------------------


def atomic_write_text(path, text: str) -> None:
    """Write ``text`` to ``path`` atomically (temp file + ``os.replace``).

    A crash mid-write leaves the original file intact, so results files are never
    left half-written.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.parent / f".{path.name}.tmp.{os.getpid()}"
    with open(tmp, "w") as f:
        f.write(text)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def atomic_write_json(path, obj) -> None:
    """Atomically write ``obj`` as pretty JSON (non-serializable values -> str)."""
    atomic_write_text(path, json.dumps(obj, indent=2, sort_keys=True, default=str))


# ---------------------------------------------------------------------------
# Task 3 helper — flatten nested config into dotted keys
# ---------------------------------------------------------------------------


def flatten_dict(d: dict, sep: str = ".", _parent: str = "") -> dict:
    """Flatten a nested dict into dotted keys, e.g. ``{"a":{"b":1}} -> {"a.b":1}``."""
    out: dict = {}
    for key, value in d.items():
        full = f"{_parent}{sep}{key}" if _parent else str(key)
        if isinstance(value, dict):
            out.update(flatten_dict(value, sep=sep, _parent=full))
        else:
            out[full] = value
    return out


# ---------------------------------------------------------------------------
# Environment / git introspection
# ---------------------------------------------------------------------------


def _git(args: list[str]) -> str | None:
    """Run a git command, returning stripped stdout or ``None`` on any failure."""
    try:
        out = subprocess.run(
            ["git", *args],
            capture_output=True,
            text=True,
            cwd=Path(__file__).resolve().parent.parent,
            timeout=10,
        )
        if out.returncode != 0:
            return None
        return out.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return None


def _env_info() -> dict:
    """Collect reproducibility metadata: git, python, torch, platform, GPU."""
    commit = _git(["rev-parse", "HEAD"])
    if commit is None:
        git_commit = "unknown"
        git_dirty = None
    else:
        git_commit = commit
        porcelain = _git(["status", "--porcelain"])
        git_dirty = bool(porcelain) if porcelain is not None else None

    info = {
        "git_commit": git_commit,
        "git_dirty": git_dirty,
        "python_version": _platform.python_version(),
        "platform": _platform.platform(),
    }

    try:
        import torch

        info["torch_version"] = torch.__version__
        cuda = bool(torch.cuda.is_available())
        info["cuda_available"] = cuda
        info["gpu_name"] = torch.cuda.get_device_name(0) if cuda else None
    except Exception:
        info["torch_version"] = "unavailable"
        info["cuda_available"] = None
        info["gpu_name"] = None

    return info


def _slugify(name: str) -> str:
    """Filesystem-safe short name."""
    slug = re.sub(r"[^A-Za-z0-9._-]+", "-", name.strip()).strip("-")
    return (slug or "run")[:40]


# ---------------------------------------------------------------------------
# Task 1/2/3 — the Run abstraction
# ---------------------------------------------------------------------------


class Run:
    """A single tracked experiment run with a unique reproducible directory."""

    def __init__(
        self,
        config: dict,
        name: str | None = None,
        base_dir: str | os.PathLike = "outputs/runs",
        results_dir: str | os.PathLike | None = None,
    ):
        self.config = config
        self.name = name or "run"
        self.base_dir = Path(base_dir)
        # Master tables live one level up from the runs dir by default.
        self.results_dir = Path(results_dir) if results_dir else self.base_dir.parent

        shortname = _slugify(self.name)
        cfg_hash = hashlib.sha1(
            json.dumps(config, sort_keys=True, default=str).encode()
        ).hexdigest()[:8]
        created = datetime.now(timezone.utc)
        # Microseconds in the timestamp keep run_ids unique even for identical
        # configs started in the same second.
        ts = created.strftime("%Y%m%dT%H%M%S_%f")
        self.run_id = f"{ts}_{shortname}_{cfg_hash}"

        self.dir = self.base_dir / self.run_id
        self.dir.mkdir(parents=True, exist_ok=True)

        self.metrics: dict = {}
        self.curves: dict = {}
        self.status = "running"
        self.created_utc = created.isoformat()

        # config.yaml + meta.json written immediately.
        atomic_write_text(self.dir / "config.yaml", yaml.safe_dump(config, sort_keys=True))
        self._meta = {
            "run_id": self.run_id,
            "name": self.name,
            "created_utc": self.created_utc,
            "status": self.status,
            "finished_utc": None,
            **_env_info(),
        }
        self._write_meta()

    # -- internal helpers ---------------------------------------------------
    def _write_meta(self) -> None:
        atomic_write_json(self.dir / "meta.json", self._meta)

    def _subdir(self, name: str) -> Path:
        d = self.dir / name
        d.mkdir(parents=True, exist_ok=True)
        return d

    # -- Task 2: logging ----------------------------------------------------
    def log_metrics(self, metrics: dict) -> None:
        """Merge scalar metrics into ``self.metrics`` and rewrite ``metrics.json``."""
        self.metrics.update(metrics)
        atomic_write_json(self.dir / "metrics.json", self.metrics)

    def log_curve(self, name: str, values: list) -> None:
        """Save a per-epoch curve (e.g. loss) to ``curves/<name>.json``."""
        values = list(values)
        self.curves[name] = values
        atomic_write_json(self._subdir("curves") / f"{name}.json", values)

    def log_artifact(self, src_path, dst_name: str | None = None) -> Path:
        """Copy an arbitrary file into ``artifacts/``; return the stored path."""
        src = Path(src_path)
        dst = self._subdir("artifacts") / (dst_name or src.name)
        shutil.copy2(src, dst)
        return dst

    def save_array(self, name: str, np_array) -> Path:
        """Save a numpy array to ``artifacts/<name>.npy``."""
        import numpy as np

        path = self._subdir("artifacts") / f"{name}.npy"
        np.save(path, np_array)
        return path

    def save_figure(self, name: str, fig) -> tuple[Path, Path]:
        """Save a matplotlib figure as both PNG (dpi 150) and vector PDF."""
        figdir = self._subdir("figures")
        png = figdir / f"{name}.png"
        pdf = figdir / f"{name}.pdf"
        fig.savefig(png, dpi=150, bbox_inches="tight")
        fig.savefig(pdf, bbox_inches="tight")
        return png, pdf

    # -- Task 3: finishing --------------------------------------------------
    def finish(self, status: str = "completed") -> None:
        """Finalize the run and append one row to the master results tables."""
        self.status = status
        atomic_write_json(self.dir / "metrics.json", self.metrics)
        self._meta["status"] = status
        self._meta["finished_utc"] = datetime.now(timezone.utc).isoformat()
        self._write_meta()

        row = {
            "run_id": self.run_id,
            "name": self.name,
            "git_commit": self._meta.get("git_commit", "unknown"),
            "status": status,
            **flatten_dict(self.config),
            **self.metrics,
        }
        self._append_results(row)

    def _append_results(self, row: dict) -> None:
        self.results_dir.mkdir(parents=True, exist_ok=True)
        csv_path = self.results_dir / "results.csv"
        jsonl_path = self.results_dir / "results.jsonl"

        # CSV: rewrite whole file with the union of columns (schema-safe).
        existing = load_results(csv_path)
        new_df = pd.DataFrame([row])
        combined = pd.concat([existing, new_df], ignore_index=True)
        atomic_write_text(csv_path, combined.to_csv(index=False))

        # JSONL: robust append-only backup, written atomically.
        prior = jsonl_path.read_text() if jsonl_path.exists() else ""
        line = json.dumps(row, sort_keys=True, default=str)
        atomic_write_text(jsonl_path, prior + line + "\n")


# ---------------------------------------------------------------------------
# Task 4 — reading results for analysis
# ---------------------------------------------------------------------------


def load_results(path: str | os.PathLike = "outputs/results.csv") -> pd.DataFrame:
    """Load the master results table; return an empty DataFrame if it's absent."""
    path = Path(path)
    if not path.exists() or path.stat().st_size == 0:
        return pd.DataFrame()
    return pd.read_csv(path)


def filter_results(df: pd.DataFrame, **equals) -> pd.DataFrame:
    """Select rows matching ``column == value`` for each keyword argument."""
    mask = pd.Series(True, index=df.index)
    for col, val in equals.items():
        if col not in df.columns:
            return df.iloc[0:0]  # no such column -> no matches
        mask &= df[col] == val
    return df[mask]


# ---------------------------------------------------------------------------
# Task 6 — end-to-end demo
# ---------------------------------------------------------------------------


def demo_run(
    base_dir: str | os.PathLike = "outputs/runs",
    results_dir: str | os.PathLike | None = None,
    extra_config: dict | None = None,
) -> Run:
    """Run a tiny fake experiment end-to-end to exercise the tracking layer."""
    import numpy as np
    import matplotlib

    matplotlib.use("Agg")  # headless
    import matplotlib.pyplot as plt

    config = {
        "geometry": {"type": "poincare", "dim": 5},
        "optim": {"lr": 0.01},
        "subtree": "bfs_s50",
        "seed": 42,
    }
    if extra_config:
        config.update(extra_config)

    run = Run(config, name="demo", base_dir=base_dir, results_dir=results_dir)
    run.log_curve("loss", [1.0, 0.5, 0.2])
    run.log_metrics({"distortion_avg": 0.12, "map": 0.87})
    run.save_array("coords", np.random.RandomState(0).randn(5, config["geometry"]["dim"]))

    fig, ax = plt.subplots()
    ax.plot([1.0, 0.5, 0.2], marker="o")
    ax.set_title("demo loss")
    run.save_figure("loss_curve", fig)
    plt.close(fig)

    run.finish()
    return run


def main(argv: list[str] | None = None) -> int:
    import argparse

    p = argparse.ArgumentParser(description="Experiment tracking layer.")
    p.add_argument("--demo", action="store_true", help="Run the end-to-end demo.")
    args = p.parse_args(argv)

    if args.demo:
        run = demo_run()
        print(f"Run directory: {run.dir}")
        df = load_results(run.results_dir / "results.csv")
        print(f"\nresults.csv tail ({len(df)} rows total):")
        print(df.tail().to_string(index=False))
    else:
        p.print_help()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
